package nl.slimov.app;
import org.json.*;import java.time.*;import java.util.*;
/** Adapter for the official NS Journey / JourneyStop / ArrivalOrDeparture schemas. */
public final class NsJourney {
 public static String id(String number,String when){return "nsjourney:"+number+":"+Instant.parse(when).toString();}
 private static JSONObject event(JSONArray list,String number)throws Exception{JSONObject found=null;if(list!=null)for(int i=0;i<list.length();i++){JSONObject e=list.optJSONObject(i);if(e!=null&&number.equals(e.optJSONObject("product")==null?"":e.getJSONObject("product").optString("number"))){if(found!=null&&!found.toString().equals(e.toString()))throw new Exception("NS rit heeft meerdere gebeurtenissen bij hetzelfde ritpunt");found=e;}}return found;}
 private static String stamp(JSONObject e,String field){return e==null?"":e.optString(field).replaceFirst("([+-]\\d{2})(\\d{2})$","$1:$2");}
 private static long time(String s){try{return Instant.parse(s).toEpochMilli();}catch(Exception e){return 0;}}
 public static JSONObject make(Object response,String number,String when)throws Exception{
  if(!number.matches("[0-9]{1,6}"))throw new Exception("Ongeldig NS-ritnummer");Instant.parse(when);JSONObject root=(JSONObject)response,payload=root.optJSONObject("payload");if(payload==null)payload=root;
  JSONArray numbers=payload.optJSONArray("productNumbers"),raw=payload.optJSONArray("stops");if(numbers==null||raw==null)throw new Exception("NS ritantwoord mist productNumbers of stops");boolean confirmed=false;for(int i=0;i<numbers.length();i++)if(number.equals(numbers.optString(i)))confirmed=true;if(!confirmed)throw new Exception("NS antwoord bevestigt dit ritnummer niet");
  Map<String,JSONObject> nodes=new LinkedHashMap<>();Map<String,JSONObject[]> events=new HashMap<>();for(int i=0;i<raw.length();i++){JSONObject n=raw.getJSONObject(i),a=event(n.optJSONArray("arrivals"),number),d=event(n.optJSONArray("departures"),number);if(a==null&&d==null&&!("PASSING".equals(n.optString("status"))&&(n.optJSONArray("arrivals")==null||n.getJSONArray("arrivals").length()==0)&&(n.optJSONArray("departures")==null||n.getJSONArray("departures").length()==0)))continue;String key=n.getString("id");if(nodes.put(key,n)!=null)throw new Exception("Dubbel NS ritpunt");events.put(key,new JSONObject[]{a,d});}
  if(nodes.size()<2)throw new Exception("NS levert onvoldoende stations voor deze rit");List<JSONObject> starts=new ArrayList<>();for(JSONObject n:nodes.values()){JSONArray prev=n.optJSONArray("previousStopId");boolean predecessor=false;if(prev!=null)for(int i=0;i<prev.length();i++)if(nodes.containsKey(prev.optString(i)))predecessor=true;if(!predecessor)starts.add(n);}if(starts.size()!=1)throw new Exception("NS routevertakking kan niet eenduidig worden gekoppeld");
  List<JSONObject> ordered=new ArrayList<>();Set<String> seen=new HashSet<>();JSONObject n=starts.get(0);while(n!=null){if(!seen.add(n.getString("id")))throw new Exception("NS route bevat een kring in ritpunten");ordered.add(n);List<JSONObject> next=new ArrayList<>();JSONArray ids=n.optJSONArray("nextStopId");if(ids!=null)for(int i=0;i<ids.length();i++){JSONObject candidate=nodes.get(ids.optString(i));if(candidate!=null)next.add(candidate);}if(next.size()>1)throw new Exception("NS route splitst voor hetzelfde ritnummer; kies de rit via het vertrekbord");n=next.isEmpty()?null:next.get(0);}if(ordered.size()!=nodes.size())throw new Exception("NS ritpunten sluiten niet volledig op elkaar aan");
  JSONArray places=new JSONArray(),codes=new JSONArray();JSONObject product=null;for(JSONObject node:ordered){JSONObject s=node.getJSONObject("stop");String code=s.optString("code");if(code.matches("[A-Za-z0-9_-]{1,12}"))codes.put(code);if("PASSING".equals(node.optString("status")))continue;double lat=s.optDouble("lat",Double.NaN),lon=s.optDouble("lng",Double.NaN);if(!Double.isFinite(lat)||!Double.isFinite(lon)||Math.abs(lat)>90||Math.abs(lon)>180||lat==0&&lon==0)throw new Exception("NS station mist bruikbare coördinaten");JSONObject[] ev=events.get(node.getString("id"));JSONObject a=ev[0],d=ev[1];if(product==null)product=(d!=null?d:a).optJSONObject("product");String uic=s.optString("UICCode"),name=s.optJSONObject("namen")==null?code:s.getJSONObject("namen").optString("lang",code);JSONObject p=new JSONObject().put("stopId",uic.isEmpty()?"ns-station:"+code:"nl-OpenOV_"+uic).put("name",name).put("lat",lat).put("lon",lon).put("stationCode",code).put("cancelled",a!=null&&a.optBoolean("cancelled")||d!=null&&d.optBoolean("cancelled"));
   for(int i=0;i<2;i++){JSONObject e=ev[i];if(e==null)continue;String kind=i==0?"arrival":"departure",planned=stamp(e,"plannedTime"),actual=stamp(e,"actualTime");if(time(planned)>0)p.put(i==0?"scheduledArrival":"scheduledDeparture",planned);if(time(actual)>0)p.put(kind,actual).put(kind+"TimestampReason","PREDICTED");else if(time(planned)>0)p.put(kind,planned);}
   JSONObject trackEvent=d!=null?d:a;p.put("track",trackEvent.optString("actualTrack",trackEvent.optString("plannedTrack"))).put("scheduledTrack",trackEvent.optString("plannedTrack"));places.put(p);
  }
  if(places.length()<2)throw new Exception("NS rit bevat minder dan twee halteerstations");JSONObject from=places.getJSONObject(0),to=places.getJSONObject(places.length()-1);String start=from.optString("departure",from.optString("arrival")),end=to.optString("arrival",to.optString("departure"));if(time(start)==0||time(end)<time(start)||time(end)-time(start)>172800000L)throw new Exception("NS rit mist geldige begin- en eindtijden");long query=Instant.parse(when).toEpochMilli();if(query<time(start)-86400000L||query>time(end)+86400000L)throw new Exception("NS antwoord past niet bij de gevraagde rijdag");
  JSONArray middle=new JSONArray();for(int i=1;i<places.length()-1;i++)middle.put(places.get(i));String type=product==null?"Trein":product.optString("longCategoryName",product.optString("shortCategoryName","Trein")),operator=product==null?"":product.optString("operatorName");JSONObject leg=new JSONObject().put("mode","RAIL").put("tripId",id(number,when)).put("tripShortName",number).put("routeShortName",type).put("agencyName",operator.isEmpty()?"Vervoerder niet doorgegeven":operator).put("agencyId",product==null?"":product.optString("operatorCode")).put("headsign",to.getString("name")).put("from",from).put("to",to).put("intermediateStops",middle).put("startTime",start).put("endTime",end).put("duration",(time(end)-time(start))/1000).put("realTime",true).put("_ns",true);
  return new JSONObject().put("legs",new JSONArray().put(leg)).put("startTime",start).put("endTime",end).put("duration",(time(end)-time(start))/1000).put("transfers",0).put("_ns",true).put("_nsNumber",number).put("_nsWhen",when).put("_stationCodes",codes).put("_fetchedAt",System.currentTimeMillis());
 }
}
